-- ============================================================================
-- StoreFlow members 2,000명 + 최근 180일 purchases 시드
--
-- consumer와 members는 연결하지 않음.
-- purchases는 members.member_id 기준으로만 연결.
-- ============================================================================

SET NAMES utf8mb4;
SET SQL_SAFE_UPDATES = 0;

-- 재적재 가능하도록 members 도메인만 초기화
DELETE FROM wishlists;
DELETE FROM purchases;
DELETE FROM members WHERE member_id BETWEEN 1 AND 2000;

ALTER TABLE purchases AUTO_INCREMENT = 1;

-- ============================================================================
-- members 2,000명
-- ============================================================================
START TRANSACTION;





COMMIT;

-- ============================================================================
-- 최근 180일 purchases
-- ============================================================================
START TRANSACTION;


























































































































































































































































































































































































































































































































COMMIT;

-- 검증
SELECT COUNT(*) AS member_count
FROM members
WHERE member_id BETWEEN 1 AND 2000;

SELECT
    COUNT(*) AS purchase_rows,
    COUNT(DISTINCT basket_id) AS basket_count,
    COUNT(DISTINCT member_id) AS purchasing_members,
    COUNT(DISTINCT sku_id) AS purchased_skus,
    MIN(purchased_at) AS first_purchase_at,
    MAX(purchased_at) AS last_purchase_at
FROM purchases;

SET SQL_SAFE_UPDATES = 1;
